function build(api) {
  api.name('Raindrop Lantern Creature');
  const C_CYAN = 0x00ced1;
  const C_CYAN_DARK = 0x008b8b;
  const C_GLOW = 0xe0ffff;
  const C_GOLD = 0xdaa520;

  // Body
  api.group('body', 'body');
  // 轮廓块：上窄下宽的雨滴灯笼型躯干
  api.cone({ rBot: 1.2, rTop: 0.3, h: 2.4, pos: [0, 1.2, 0], along: '+Y', color: C_CYAN });
  // 特征块：内部发光核心
  api.sphere({ r: 0.6, pos: [0, 1.0, 0], color: C_GLOW });
  // 特征块：底部圆润收束
  api.sphere({ r: 1.2, pos: [0, 0.3, 0], color: C_CYAN });
  // 色块面：正面浅色光泽面
  api.tri({ a: [-0.8, 0.4, 1.15], b: [0.8, 0.4, 1.15], c: [0, 2.2, 1.15], d: 0.06, color: C_GLOW });
  // 细节块：顶部小提环
  api.torus({ r: 0.2, tube: 0.06, pos: [0, 2.55, 0], along: '+Y', color: C_GOLD });
  // 细节块：底部尖端装饰
  api.poly({ r: 0.12, pos: [0, 0.05, 0], color: C_GOLD });
  // 细节块：正面羞涩的小眼睛
  api.poly({ r: 0.18, pos: [0.35, 1.4, 1.05], color: 0x1a1a1a });
  api.poly({ r: 0.18, pos: [-0.35, 1.4, 1.05], color: 0x1a1a1a });
  api.endGroup();

  // Left Leg
  api.group('leftLeg', 'leftLeg');
  api.cyl({ r: 0.15, h: 0.3, pos: [-0.4, 0.15, 0.2], along: '+Y', color: C_CYAN_DARK });
  api.sphere({ r: 0.2, pos: [-0.4, 0.05, 0.25], color: C_CYAN });
  api.endGroup();

  // Right Leg
  api.group('rightLeg', 'rightLeg');
  api.cyl({ r: 0.15, h: 0.3, pos: [0.4, 0.15, 0.2], along: '+Y', color: C_CYAN_DARK });
  api.sphere({ r: 0.2, pos: [0.4, 0.05, 0.25], color: C_CYAN });
  api.endGroup();
}
